// Privremeno: dohvacamo sve pa filtriramo u memoriji.
// Zamijeniti upitom s WHERE kad tablica prijede
// ~10k redaka (sada ih je 400). Vidi #214.

function prosjek(brojevi) {
  return brojevi.reduce((a, b) => a + b) / brojevi.length;
}

